import{d as g,C as n,o as u,c as h,a3 as i,E as t,j as a,a as d}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"论语·微子","description":"《论语》第 18 篇「微子」——十一章原文与导读。殷有三仁、直道而事人、楚狂接舆、长沮桀溺、荷蓧丈人、逸民与「无可无不可」。","frontmatter":{"title":"论语·微子","description":"《论语》第 18 篇「微子」——十一章原文与导读。殷有三仁、直道而事人、楚狂接舆、长沮桀溺、荷蓧丈人、逸民与「无可无不可」。","category":"guide","aliases":["微子","微子篇","微子第十八","论语微子","lunyu 微子"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-18.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-18.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-18.md"},w=g({...p,setup(m){const r=[{id:"yi",label:"一、殷有三仁焉",showLabel:!0,sentences:[["微子去之，箕子为之奴，比干谏而死。孔子曰：“殷有三仁焉。”"]],note:"「微子去之，箕子为之奴，比干谏而死」——微子离去，箕子为奴（佯狂），比干谏而死。「孔子曰：殷有三仁焉」——殷有三仁。"},{id:"er",label:"二、直道而事人",showLabel:!0,sentences:[["柳下惠为士师，三",{text:"黜",glossary:"chu"},"。人曰：“子未可以去乎？”曰：“直道而事人，焉往而不三黜？枉道而事人，何必去父母之邦？”"]],note:"柳下惠为士师，三黜。人曰：「子未可以去乎」——您不可离去吗？曰：「直道而事人，焉往而不三黜？枉道而事人，何必去父母之邦」——以直道事人，往何处而不三黜？若以枉道事人，又何必离开父母之邦？"},{id:"san",label:"三、齐景公待孔子",showLabel:!0,sentences:[["齐景公待孔子曰：“若季氏，则吾不能。”以季、孟之间待之，曰：“吾老矣，不能用也。”孔子行。"]],note:"齐景公待孔子曰：「若季氏，则吾不能」——若如季氏那般，则我不能。「以季、孟之间待之」，曰：「吾老矣，不能用也」。孔子行。"},{id:"si",label:"四、齐人归女乐",showLabel:!0,sentences:[["齐人归女乐，季桓子受之，三日不朝，孔子行。"]],note:"齐人归（馈）女乐，季桓子受之，三日不朝。孔子行。"},{id:"wu",label:"五、楚狂接舆",showLabel:!0,sentences:[["楚狂接舆歌而过孔子曰：“凤兮凤兮，何德之衰？往者不可谏，来者犹可追。已而已而，今之从政者",{text:"殆",glossary:"dai-wei2"},"而！”孔子下，欲与之言，趋而",{text:"辟",glossary:"bi-bi3"},"之，不得与之言。"]],note:"楚狂接舆歌而过孔子曰：「凤兮凤兮，何德之衰？往者不可谏，来者犹可追。已而已而，今之从政者殆而」——凤啊凤啊，何德之衰？往者不可谏，来者犹可追；算了吧算了吧，今之从政者危矣！孔子下，欲与之言，趋而避之，不得与之言。"},{id:"liu",label:"六、长沮、桀溺耦而耕",showLabel:!0,sentences:[["长沮、桀溺",{text:"耦而耕",glossary:"ouergeng"},"，孔子过之，使子路问津焉。长沮曰：“夫执舆者为谁？”子路曰：“为孔丘。”曰：“是鲁孔丘与？”曰：“是也。”曰：“是知津矣。”问于桀溺，桀溺曰：“子为谁？”曰：“为仲由。”曰：“是鲁孔丘之徒与？”对曰：“然。”曰：“滔滔者天下皆是也，而谁以易之？且而与其从辟人之士也，岂若从辟世之士？”",{text:"耰而不辍",glossary:"youerbuchuo"},"。子路行以告，夫子",{text:"怃然",glossary:"wuran"},"曰：“鸟兽不可与同群，吾非斯人之徒与而谁与？天下有道，丘不与易也。”"]],note:"长沮、桀溺耦而耕。孔子过之，使子路问津焉。长沮曰：「夫执舆者为谁」？曰「为孔丘」。曰「是鲁孔丘与」？曰「是也」。曰：「是知津矣」。问于桀溺，曰：「子为谁」？曰「为仲由」。曰「是鲁孔丘之徒与」？曰「然」。桀溺曰：「滔滔者天下皆是也，而谁以易之？且而与其从辟人之士也，岂若从辟世之士哉」——天下滔滔皆是，谁能易之？且汝与其从避人之士，岂若从避世之士。耰而不辍。子路以告，夫子怃然曰：「鸟兽不可与同群，吾非斯人之徒与而谁与？天下有道，丘不与易也」——鸟兽不可与同群，我不与斯人同道又与谁？天下若有道，丘不与之易。"},{id:"qi",label:"七、子路从而后，遇丈人",showLabel:!0,sentences:[["子路从而后，遇丈人，以杖荷",{text:"蓧",glossary:"diao-nong"},"。子路问曰：“子见夫子乎？”丈人曰：“四体不勤，五谷不分，孰为夫子？”植其杖而芸，子路拱而立。止子路宿，杀鸡为黍而食之，见其二子焉。明日，子路行以告，子曰：“隐者也。”使子路反见之，至则行矣。子路曰：“不仕无义。长幼之节不可废也，君臣之义如之何其废之？欲洁其身而乱大伦。君子之仕也，行其义也，道之不行已知之矣。”"]],note:"子路从而后，遇丈人以杖荷蓧。子路问曰：「子见夫子乎」？丈人曰：「四体不勤，五谷不分，孰为夫子」？植其杖而芸。子路拱而立。止子路宿，杀鸡为黍而食之，见其二子焉。明日，子路行以告，子曰「隐者也」，使子路反见之，至则行矣。子路曰：「不仕无义。长幼之节，不可废也；君臣之义，如之何其废之？欲洁其身，而乱大伦。君子之仕也，行其义也。道之不行，已知之矣」。"},{id:"ba",label:"八、逸民：伯夷、叔齐",showLabel:!0,sentences:[["逸民：伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连。子曰：“不降其志，不辱其身，伯夷、叔齐与！”谓：“柳下惠、少连降志辱身矣，言中伦，行中虑，其斯而已矣。”谓：“虞仲、夷逸隐居放言，身中清，废中权。我则异于是，",{text:"无可无不可",glossary:"wukebukeweike"},"。”"]],note:"「逸民：伯夷、叔齐、虞仲、夷逸、朱张、柳下惠、少连」。孔子评曰：「不降其志，不辱其身，伯夷、叔齐与」！谓：「柳下惠、少连降志辱身矣，言中伦，行中虑，其斯而已矣」；谓：「虞仲、夷逸隐居放言，身中清，废中权」。「我则异于是，无可无不可」——我与他们都不同：无可无不可。"},{id:"jiu",label:"九、太师挚适齐",showLabel:!0,sentences:[["太师挚适齐，亚饭干适楚，三饭缭适蔡，四饭缺适秦，鼓方叔入于河，播",{text:"鼗",glossary:"tao"},"武入于汉，少师阳、击磬襄入于海。"]],note:"「太师挚适齐，亚饭干适楚，三饭缭适蔡，四饭缺适秦，鼓方叔入于河，播鼗武入于汉，少师阳、击磬襄入于海」——鲁国乐官四散：太师挚去齐、亚饭干去楚、三饭缭去蔡、四饭缺去秦、鼓方叔入居河滨、播鼗武入居汉滨、少师阳与击磬襄入居海岛。见礼乐之崩坏。"},{id:"shi",label:"十、周公谓鲁公曰",showLabel:!0,sentences:[["周公谓鲁公曰：“君子不",{text:"施",glossary:"shi-chi"},"其亲，不使大臣怨乎不以，故旧无大故则不弃也，无求备于一人。”"]],note:"周公谓鲁公曰：「君子不施其亲（施＝弛、遗弃），不使大臣怨乎不以，故旧无大故则不弃也，无求备于一人」——君子不遗弃其亲族，不使大臣怨其不见用，故旧无大过则不弃，且不求全责备于一人。"},{id:"shiyi",label:"十一、周有八士",showLabel:!0,sentences:[["周有八士：伯达、伯适、仲突、仲忽、叔夜、叔夏、季随、季",{text:"騧",glossary:"gua"},"。"]],note:"「周有八士：伯达、伯适、仲突、仲忽、叔夜、叔夏、季随、季騧」——周有八士（八位贤士），记周初人才之盛。"}],o=[{id:"chu",term:"黜",pinyin:"chù",meaning:"罢免、贬退。三黜：三次被罢免。"},{id:"dai-wei2",term:"殆",pinyin:"dài",meaning:"危险。今之从政者殆而：如今从政的人危险啊。"},{id:"bi-bi3",term:"辟",pinyin:"bì",meaning:"同「避」。趋而辟之：快步避开他。"},{id:"ouergeng",term:"耦而耕",pinyin:"ǒu ér gēng",meaning:"两人并肩耕作。耦：两人并耕。"},{id:"youerbuchuo",term:"耰而不辍",pinyin:"yōu ér bù chuò",meaning:"耰：播种后用土覆盖、耙平；辍：停止。仍继续干活不停手（表示不愿再谈）。"},{id:"wuran",term:"怃然",pinyin:"wǔ rán",meaning:"怅然失意、心中不乐的样子。"},{id:"diao-nong",term:"蓧",pinyin:"diào",meaning:"除草用的竹器。以杖荷蓧：用拐杖挑着除草的工具。"},{id:"wukebukeweike",term:"无可无不可",pinyin:"wú kě wú bù kě",meaning:"没有什么一定可以，也没有什么一定不可以——依义而行，不预设立场。此为孔子自述与逸民之别。"},{id:"tao",term:"鼗",pinyin:"táo",meaning:"拨浪鼓（一种有柄的小鼓）。"},{id:"shi-chi",term:"施",pinyin:"shī",meaning:"同「弛」，疏远、怠慢（一说「施」为「遗弃」）。不施其亲：不怠慢自己的亲族。"},{id:"gua",term:"騧",pinyin:"guā",meaning:"黑嘴的黄马（此处为人名用字）。"}];return(c,e)=>{const s=n("DaoTextReading"),l=n("DaoKeywordCards");return u(),h("div",null,[e[0]||(e[0]=i('<h1 id="论语·微子" tabindex="-1">论语·微子 <a class="header-anchor" href="#论语·微子" aria-label="Permalink to &quot;论语·微子&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《微子》十一章，是**《论语》中「隐者」出现最多的一篇**。孔子在这里一再遇到不愿出世的人：楚狂接舆唱着歌从他车前走过，长沮桀溺在田里耕地不理他，荷蓧丈人说他「四体不勤，五谷不分」。</p><p><strong>这一篇的重心是「仕与隐」的对辩。</strong> 隐者的立场很清楚：天下滔滔，谁都改变不了，不如躲开。孔子的回答也清楚——「鸟兽不可与同群，吾非斯人之徒与而谁与？」而子路替老师说的那句更直接：<strong>「君子之仕也，行其义也，道之不行已知之矣。」</strong> 明知不行而仍要行，是这一篇的底色。</p><p>开篇「殷有三仁焉」（微子、箕子、比干三种不同的选择）与第八章「逸民」（伯夷叔齐「不降其志，不辱其身」，孔子说自己「<strong>无可无不可</strong>」），是《论语》中对「出处进退」最集中的讨论。末两章转向旧制旧人：鲁国乐师四散、周公训诫鲁公、周有八士——<strong>像一份黄昏中的名单。</strong></p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',6)),t(s,{colophon:"微子第十八 · 十一章",tone:"ink",sections:r,glossary:o,"default-mode":"slips","aria-label":"论语·微子 原文"}),e[1]||(e[1]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"黜",pinyin:["chù"],meaning:"罢免、贬退。三黜：三次被罢免。"},{term:"殆",pinyin:["dài"],meaning:"危险。今之从政者殆而：如今从政的人危险啊。"},{term:"辟",pinyin:["bì"],meaning:"同「避」。趋而辟之：快步避开他。"},{term:"耦而耕",pinyin:["ǒu","ér","gēng"],meaning:"两人并肩耕作。耦：两人并耕。"},{term:"耰而不辍",pinyin:["yōu","ér","bù","chuò"],meaning:"耰：播种后用土覆盖、耙平；辍：停止。仍继续干活不停手（表示不愿再谈）。"},{term:"怃然",pinyin:["wǔ","rán"],meaning:"怅然失意、心中不乐的样子。"},{term:"蓧",pinyin:["diào"],meaning:"除草用的竹器。以杖荷蓧：用拐杖挑着除草的工具。"},{term:"无可无不可",pinyin:["wú","kě","wú","bù","kě"],meaning:"没有什么一定可以，也没有什么一定不可以——依义而行，不预设立场。此为孔子自述与逸民之别。"},{term:"鼗",pinyin:["táo"],meaning:"拨浪鼓（一种有柄的小鼓）。"},{term:"施",pinyin:["shī"],meaning:"同「弛」，疏远、怠慢（一说「施」为「遗弃」）。不施其亲：不怠慢自己的亲族。"},{term:"騧",pinyin:["guā"],meaning:"黑嘴的黄马（此处为人名用字）。"}]}),e[2]||(e[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《微子》十一章，核心是**「仕还是隐」这场对辩**。</p><p><strong>隐者一方</strong>，立场有四种。楚狂接舆唱歌讥讽（天下已不可救，何苦奔波）；长沮桀溺埋头耕地（滔滔者天下皆是，谁能改变，不如避世）；荷蓧丈人用「四体不勤，五谷不分」挖苦（不事生产的人算什么老师）；以及第八章列出的逸民七人（不降其志不辱其身，或降志辱身而有守）。</p><p><strong>孔子一方</strong>，回答也极清楚。他的选择是「吾非斯人之徒与而谁与」——<strong>正因为人是人群中人，不能躲开人群</strong>；子路替他补得更明白：「君子之仕也，行其义也，道之不行已知之矣。」<strong>出来做事不是为了成，是为了该做。</strong></p><p>开篇与第八章，是同一问题的另一种写法：微子去、箕子奴、比干死——<strong>同是殷臣，三种选择都被孔子称为「仁」</strong>；而孔子对自己的总结是「<strong>无可无不可</strong>」——<strong>不预设立场，依义而行。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它对「隐者」的态度值得细看</strong>：孔子不贬低他们，反而称荷蓧丈人为「隐者」；第八章也一一评论逸民的长处。<strong>反对归反对，敬重归敬重——这是孔子少见的「不争而有余味」。</strong></li><li><strong>它给出了「知其不可而为之」的正面论述</strong>：子路那句「道之不行已知之矣」，是全书对孔子一生最准确的解释——<strong>不是因为看得准才去做，而是因为该做才去做。</strong></li><li><strong>「殷有三仁」说明了「仁」不是一个模子</strong>：微子选择离开，箕子选择忍辱为奴，比干选择死谏——<strong>三种做法完全不同，孔子却都称之为仁</strong>。这是《论语》最通达的一段。</li><li><strong>「无可无不可」是极高明的处世尺度</strong>：它不是没有原则的随波逐流，而是<strong>不把手段固定下来，只守住「义」这个方向。</strong></li><li><strong>它保存了鲁国衰落的侧影</strong>：齐人归女乐、季桓子三日不朝、太师挚以下乐师四散——<strong>这几章几乎是一份亡国档案</strong>，也解释了孔子为什么离开鲁国。</li><li><strong>末章的「无求备于一人」是极好的用人观</strong>：<strong>不苛求一个人样样都行</strong>。这与《子路》「赦小过」、《宪问》「器之」是同一路思路。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>「直道而事人」当职业操守的底牌</strong>：用正道做事，就别指望处处顺利；用歪道做事，到哪儿都一样**——所以要么换做法，要么不必换地方。**</li><li><strong>对「隐者」保持敬意</strong>：不同的人生选择不一定有一个是错的。<strong>可以不认同，不必看轻。</strong></li><li><strong>用「无可无不可」对抗路径依赖</strong>：目标是守住义，方法可以换。<strong>别把某个具体做法当成原则本身。</strong></li><li><strong>用「无求备于一人」对待同事与伙伴</strong>：看人看长处，别指望一个人同时具备所有优点。</li><li><strong>遇到「说了也没用」的局面，学子路那句</strong>：「道之不行已知之矣」——<strong>做这件事的意义不在结果，在它本身就是对的。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《微子》这篇里，孔子一直在路上——不是遇到隐士，就是被隐士劝说。</p><p>一个叫接舆的楚国人，唱着歌从他车前过去：「凤啊凤啊，你的德行为什么衰败了？过去的追不回了，将来的还来得及。算了吧，算了吧，如今从政的人危险。」孔子下车想和他说话，他快步走开了。</p><p>又有两个人，长沮和桀溺，在田里并肩耕地。子路去问渡口，他们反问：你是孔丘的学生吧？天下像洪水一样，你和谁去改变它？与其跟着避开坏人的孔子，不如跟着避开整个社会的我们。说完继续干活，不再理人。</p><p>孔子听了，怅然说：人不能跟鸟兽一起生活。我不跟人在一起，跟谁在一起？<strong>如果天下有道，我还去改变它干什么。</strong></p><p>后来子路又碰到一位老人，用拐杖挑着锄草工具。子路问见没见到我老师，老人说：「四体不勤，五谷不分，谁是你的老师？」然后留子路住下，杀鸡做饭招待他。</p><p>孔子说，那是位隐者。</p><p>子路后来讲了一段话，是这篇的中心：不出来做事是没有道理的。长幼的礼节不能废，君臣的大义怎么能废？为了自己干净而搅乱更大的伦理，不行。<strong>君子出来做事，是为了尽他该尽的义——道行不通，早就知道了。</strong></p><p>第十一章只有一句，列了八个名字。像是一份黄昏里的名单。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「直道而事人，焉往而不三黜」——我在工作上遇到过类似的处境吗？我是怎么处理的？</li><li>「鸟兽不可与同群」——我有没有过想「退出、不管了」的念头？后来怎么想的？</li><li>「道之不行已知之矣」——我有没有一件明知成效有限、但仍在做的事？它对我意味着什么？</li><li>「殷有三仁」——同一种处境可以有完全不同的应对。如果换成我，我会是微子（离开）、箕子（忍辱）还是比干（死谏）？</li><li>「无可无不可」——我是不是在某个具体做法上过于固执？那到底是原则，还是习惯？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-17">论语·阳货</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-19">论语·子张</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',26))])}}});export{y as __pageData,w as default};
